sys_script_include.script:
var TaskUtils = Class.create();
TaskUtils.prototype = {
    initialize: function() {
    },
	  getTasksByEvent: function(eventId) {
        var tasks = [];
        var taskGR = new GlideRecord('x_1790139_event_ma_event_task');
        taskGR.addQuery('x_event_id', eventId);
        taskGR.query();
        while (taskGR.next()) {
            tasks.push({
                sys_id: taskGR.getUniqueValue(),
                name: taskGR.getDisplayValue('x_task_name'),
                due_date: taskGR.getValue('x_due_date'),
                state: taskGR.getDisplayValue('x_status')
            });
        }
        return tasks;
    },
	 isTaskOverdue: function(taskId) {
        var taskGR = new GlideRecord('x_1790139_event_ma_event_task');
        if (taskGR.get(taskId)) {
            var dueDate = new GlideDateTime(taskGR.getValue('x_due_date'));
            var now = new GlideDateTime();
            return dueDate.before(now);
        }
        return false;
    },
	 getTaskDetails: function(taskId) {
        var taskGR = new GlideRecord('x_1790139_event_ma_event_task');
        if (taskGR.get(taskId)) {
            return {
                sys_id: taskGR.getUniqueValue(),
                name: taskGR.getDisplayValue('x_task_name'),
                due_date: taskGR.getValue('x_due_date'),
                state: taskGR.getDisplayValue('x_status'),
                assigned_to: taskGR.getDisplayValue('x_assigned_to')
            };
        }
        return null;
    },
	 getTasksByDueDate: function(dateStr) {
        var tasks = [];
        var taskGR = new GlideRecord('x_1790139_event_ma_event_task');
        taskGR.addQuery('x_due_date', dateStr);
        taskGR.query();
        while (taskGR.next()) {
            tasks.push({
                sys_id: taskGR.getUniqueValue(),
                name: taskGR.getDisplayValue('x_task_name'),
                due_date: taskGR.getValue('x_due_date'),
            });
        }
        return tasks;
    },


    type: 'TaskUtils'
};
